-- Тема 12: уточнения по проверке Codex (30 исправлений в 11 вопросах), ключи не меняются.
-- Источник: scripts/questions/086_codex_topic12_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Какое расширение собирает статистику по выполняемым запросам?', NULL, NULL, NULL, 'Какое расширение накапливает число выполнений, время и число строк по нормализованным запросам?'),
        ('question', 'Какой параметр записывает в журнал команды, выполнявшиеся дольше заданного времени?', NULL, NULL, NULL, 'Какой параметр задаёт порог длительности для записи завершённых команд в журнал?'),
        ('question', 'Как часто обслуживающий процесс записывает собранную статистику в разделяемую память?', NULL, NULL, NULL, 'Какой минимальный интервал между штатными непринудительными выгрузками накопительной статистики задан в стандартной сборке PostgreSQL 16?'),
        ('question', 'Коллектор сообщений включён, журнал пишется в одном формате (log_destination = ''stderr''). Сколько файлов журнала сообщений получится при log_filename = ''postgresql-%a.log'', ротации раз в сутки и log_truncate_on_rotation = on?', NULL, NULL, NULL, 'Коллектор сообщений включён, журнал пишется в одном формате (log_destination = ''stderr''). Сколько различных имён файлов журнала используется в недельном цикле при log_filename = ''postgresql-%a.log'', ротации раз в сутки и log_truncate_on_rotation = on?'),
        ('question', 'Что делает параметр log_truncate_on_rotation = on?', NULL, NULL, NULL, 'Что делает параметр log_truncate_on_rotation = on при ротации журнала по времени?'),
        ('question', 'Можно ли средствами PostgreSQL ограничить роли объём занимаемого на диске места?', NULL, NULL, NULL, 'Как действуют дисковые квоты для PostgreSQL?'),
        ('option', 'Какое расширение накапливает число выполнений, время и число строк по нормализованным запросам?', 'Расширение pg_wait_sampling', NULL, 'Стороннее расширение, собирает статистику ожиданий.', 'Собирает выборочный профиль ожиданий, в том числе по queryid, а не указанный набор счётчиков выполнения.'),
        ('option', 'Какое расширение накапливает число выполнений, время и число строк по нормализованным запросам?', 'Расширение pg_stat_statements', NULL, 'Число вызовов, время, строки для каждого запроса.', 'Агрегирует число вызовов, время и строки по группам одинаковых (нормализованных) запросов.'),
        ('option', 'Что нужно, чтобы использовать приёмники журнала csvlog и jsonlog?', 'Включённый коллектор сообщений сервера', 'Работающий коллектор сообщений', 'Эти форматы пишет только коллектор.', NULL),
        ('option', 'Какой параметр задаёт порог длительности для записи завершённых команд в журнал?', 'log_duration — время всех команд', 'log_autovacuum_min_duration', 'Записывает время всех команд.', 'Задаёт порог для записи действий автоочистки, а не обычных команд.'),
        ('option', 'Какой параметр задаёт порог длительности для записи завершённых команд в журнал?', 'log_statement — тексты команд', 'log_min_error_statement', 'Записывает текст команд выбранных типов.', 'Определяет, при каком уровне ошибки в журнал попадает текст команды, а не порог длительности.'),
        ('option', 'Какой параметр задаёт порог длительности для записи завершённых команд в журнал?', 'log_min_duration_statement — долгие команды', 'log_min_duration_statement', 'Записывает команды не короче порога; 0 — все, -1 — отключено.', NULL),
        ('option', 'Какой параметр задаёт порог длительности для записи завершённых команд в журнал?', 'log_lock_waits — долгие ожидания блокировок', 'log_duration', 'Записывает долгие ожидания блокировок.', 'Записывает длительность всех завершённых команд, а не только долгих.'),
        ('option', 'Какой минимальный интервал между штатными непринудительными выгрузками накопительной статистики задан в стандартной сборке PostgreSQL 16?', 'Не чаще раза в секунду', 'Одна секунда', 'Интервал задан при компиляции.', 'Обычные выгрузки ограничены интервалом PGSTAT_MIN_INTERVAL = 1000 мс; реальная публикация может произойти позже. Принудительная выгрузка при завершении процесса рассматривается отдельно.'),
        ('option', 'Какой минимальный интервал между штатными непринудительными выгрузками накопительной статистики задан в стандартной сборке PostgreSQL 16?', 'После выполнения каждого запроса', 'Одна миллисекунда', 'Это было бы слишком накладно.', 'Интервал в миллисекунду создавал бы слишком большие накладные расходы.'),
        ('option', 'Какой минимальный интервал между штатными непринудительными выгрузками накопительной статистики задан в стандартной сборке PostgreSQL 16?', 'При остановке сервера', 'Одна минута', 'Статистика сохраняется на диск при остановке, но обслуживающий процесс записывает её в разделяемую память гораздо чаще.', 'В стандартной сборке интервал намного короче минуты.'),
        ('option', 'Какой минимальный интервал между штатными непринудительными выгрузками накопительной статистики задан в стандартной сборке PostgreSQL 16?', 'При каждой контрольной точке', 'Один час', 'Контрольная точка к статистике не относится.', 'В стандартной сборке интервал намного короче часа.'),
        ('option', 'Что делает значение stats_fetch_consistency = snapshot?', 'Кеширует статистику по одному объекту', 'Кеширует статистику объектов по мере чтения', 'Так не делает ни одно значение; при cache, используемом по умолчанию, статистика кешируется отдельно для каждого объекта при первом обращении.', 'Это режим cache: при первом обращении кешируется статистика соответствующего объекта. snapshot формирует общий снимок.'),
        ('option', 'Что делает значение stats_fetch_consistency = snapshot?', 'Кеширует статистику базы до конца транзакции', 'Создаёт общий снимок статистики текущей базы', 'Даёт самую согласованную картину ценой затрат на кеширование.', 'Общий снимок статистики текущей базы даёт самую согласованную картину ценой затрат на кеширование.'),
        ('option', 'Как сбросить закешированную в процессе статистику раньше конца транзакции?', 'Вызвать функцию pg_reload_conf() сервера', 'Вызвать функцию pg_reload_conf()', 'Эта функция перечитывает конфигурацию.', NULL),
        ('option', 'Что верно для коллектора сообщений?', 'Он включён по умолчанию при установке', 'В стандартной конфигурации включён по умолчанию', 'По умолчанию logging_collector = off.', NULL),
        ('option', 'Что верно для коллектора сообщений?', 'Он не теряет сообщения при нагрузке', NULL, 'В отличие от syslog, коллектор не теряет сообщения.', 'В отличие от syslog, коллектор не теряет сообщения при нагрузке: отправители ждут, а не отбрасывают их. Это не гарантия при отказе диска.'),
        ('option', 'Что верно для коллектора сообщений?', 'Он работает с приёмником syslog', 'Он пересылает собранные сообщения демону syslog', 'Он записывает в файлы stderr, csvlog и jsonlog, а не в syslog.', 'Маршрут syslog работает отдельно; коллектор пишет файловые журналы. Их одновременное включение допустимо.'),
        ('option', 'Что делает параметр log_truncate_on_rotation = on при ротации журнала по времени?', 'Перезаписывает файл с тем же именем при ротации', 'Усекает одноимённый файл при ротации', 'При ротации по времени перезаписывает уже существующий файл с тем же именем; иначе новые сообщения дописывались бы в конец старого файла.', 'При ротации по времени перезаписывает уже существующий файл с тем же именем; запуск сервера и ротация по размеру такого эффекта не дают; иначе новые сообщения дописывались бы в конец старого файла.'),
        ('option', 'Какое ограничение есть у анализатора журналов pgBadger?', 'Он обрабатывает журналы баз до 1 ГБ', 'Он требует, чтобы размер базы был меньше 1 ГБ', 'Такого ограничения нет: размер базы не важен.', 'Такого предела размера базы у анализатора журналов нет.'),
        ('option', 'Как действуют дисковые квоты для PostgreSQL?', 'Да, командой ALTER ROLE с ограничением объёма', 'Роли можно ограничить командой ALTER ROLE', 'Такой возможности в PostgreSQL нет.', NULL),
        ('option', 'Как действуют дисковые квоты для PostgreSQL?', 'Нет: квоты задаются средствами ОС для сервера', 'Квота ОС задаётся для пользователя сервера', 'Квоты задаются средствами ОС для пользователя ОС, под которым работает сервер; квота для этого пользователя должна быть достаточной.', 'Встроенных дисковых квот для ролей нет: квоты задаются средствами ОС для пользователя ОС, под которым работает сервер; квота для этого пользователя должна быть достаточной.'),
        ('option', 'Как действуют дисковые квоты для PostgreSQL?', 'Да, параметром work_mem для роли', 'Квоту роли задаёт параметр work_mem', 'work_mem ограничивает память для операций, а не место на диске.', NULL),
        ('option', 'Как действуют дисковые квоты для PostgreSQL?', 'Да, через табличные пространства сервера', 'Квоту задают табличные пространства сервера', 'Табличные пространства определяют размещение данных, а не квоты.', NULL),
        ('explanation', 'Что делает значение stats_fetch_consistency = snapshot?', NULL, NULL, 'Закешированная статистика не перечитывается до конца транзакции.', 'Закешированный снимок статистики обычно не перечитывается до конца транзакции; его сбрасывает pg_stat_clear_snapshot() или смена stats_fetch_consistency.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
